    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)

    # Each run of exactly repeated cells on the dominant axis gets a marker at
    # the missing location where the same pattern has an interruption.
    # For long horizontal rails, complete gaps between colored points.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        if len(cols) >= 4:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == bg:
                        out[r][c] = 2

