    # column, plus one missing aligned point on a rail parallel to a longer one.
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(rows, rows[1:]):
            if b - a == 2:
                out[a + 1][c] = 2

    # The frame has two aligned side rails. Fill the sole absent left-side point
    # in a row where the right side is present and neighboring left cells exist.
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    rmin, rmax = min(r for r, c in points), max(r for r, c in points)
