 "content": "def transform(grid):
    """Insert 2s along near-complete straight lines of the foreground color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(value for value in counts if value != bg)

    # Fill foreground gaps when there are marks on both sides of the gap.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Also color edge interruptions, where a long repeated run along the
    # boundary starts/ends with gaps in the otherwise dominant edge pattern.
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == fg]
    r0, r1 = min(r for r, c in pts), max(r for r, c in pts)
    c0, c1 = min(c for r, c in pts), max(c for r, c in pts)
    for r in (r0, r1):
        cs = [c for c in range(c0, c1 + 1) if grid[r][c] == fg]
        if len(cs) >= 3:
            for c in range(min(cs), max(cs) + 1):
