    marked with 2. Background cells inside the rectangle remain unchanged.
    """
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next((value for value in counts if value != background), None)
    if foreground is None:
        return out

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    if not points:
        return out
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            if (r == r0 or r == r1 or c == c0 or c == c1) and grid[r][c] == background:
                out[r][c] = 2
    return out

