    """Color the missing point(s) where orthogonal line segments nearly meet."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)

    # First mark all cells between aligned foreground marks as demonstrated.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == fg]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == fg]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Also color a missing corner/turn where the figure's horizontal and
    # vertical bars meet: a blank cell with a colored neighbor on each axis.
    # Do this from the input, so marker additions don't propagate.
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                continue
            horiz = ((c > 0 and grid[r][c-1] == fg) or
                     (c+1 < w and grid[r][c+1] == fg))
            vert = ((r > 0 and grid[r-1][c] == fg) or
                    (r+1 < h and grid[r+1][c] == fg))
            # A turn is evidenced by each axis having two foreground marks
            # within a short distance, even if not directly adjacent.
            left = any(grid[r][x] == fg for x in range(max(0,c-2),c))
            right = any(grid[r][x] == fg for x in range(c+1,min(w,c+3)))
            up = any(grid[y][c] == fg for y in range(max(0,r-2),r))
            down = any(grid[y][c] == fg for y in range(r+1,min(h,r+3)))
            if (left and right) or (up and down) or (horiz and vert and (left or right or up or down)):
                out[r][c] = 2
    return out
