    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next(value for value in counts if value != background)

    # A line is established by at least three original foreground samples.
    # Fill only the interval between its extreme samples, using marker 2.
    for r in range(h):
        positions = [c for c in range(w) if grid[r][c] == foreground]
        if len(positions) >= 3:
