 "content": "def transform(grid):
    """Recolor each singleton color point that interrupts a straight pattern to 2."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    # Target is the non-background color that appears least often; other
    # non-background color(s) serve as the surrounding pattern.
    colors = [v for v in counts if v != background]
    if not colors:
        return out
    target = min(colors, key=lambda v: counts[v])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != target:
                continue
            # The demos show marked cells occur as isolated points amid a
            # dominant other color, and are changed to 2 when flanked along
            # any row/column by that dominant foreground color.
            neighbors = []
            for dr, dc in ((0,1),(0,-1),(1,0),(-1,0)):
                rr, cc = r+dr, c+dc
                if 0 <= rr < h and 0 <= cc < w:
                    neighbors.append(grid[rr][cc])
            if any(v != background and v != target for v in neighbors):
                out[r][c] = 2
    return out

if __name__ == '__main__':
    pass
