 "content": "def transform(grid):
    """Complete dense rows and columns across the foreground bounding box."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next(value for value in counts if value != background)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    if not points:
        return out

    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    # A line is a complete stroke when it contains at least three original
    # foreground marks. Extend that stroke over the foreground's full bounds.
    for r in range(rmin, rmax + 1):
        if sum(grid[r][c] == foreground for c in range(w)) >= 3:
            for c in range(cmin, cmax + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(cmin, cmax + 1):
        if sum(grid[r][c] == foreground for r in range(h)) >= 3:
            for r in range(rmin, rmax + 1):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

