 "content": "def transform(grid):
    """Highlight missing cells between aligned marks and on their bounding frame."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    foreground = next(value for value in counts if value != background)
    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == foreground]
    if not points:
        return out
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)

    # Complete the outer rectangular frame around the marked pattern.
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if (r == rmin or r == rmax or c == cmin or c == cmax):
                if grid[r][c] == background:
                    out[r][c] = 2

    # Highlight background gaps between original marks sharing a row/column.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == foreground]
        for left, right in zip(cols, cols[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == foreground]
        for top, bottom in zip(rows, rows[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out

